import numpy as np


def q391(cache, new_keys, new_values):
    if cache is None:
        return (
            np.array(new_keys, copy=True),
            np.array(new_values, copy=True),
        )
    return (
        np.concatenate((cache[0], new_keys), axis=-2),
        np.concatenate((cache[1], new_values), axis=-2),
    )
